import AppKit
import ApplicationServices

/// Следит за системным буфером и складывает всё скопированное в историю.
final class ClipboardWatcher {
    let store: ClipStore
    var paused = false
    var onNewItem: ((ClipItem) -> Void)?

    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    /// Менеджеры паролей помечают секреты этими типами — их не сохраняем.
    private let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]

    init(store: ClipStore) { self.store = store }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.35, repeats: true) { [weak self] _ in self?.check() }
        timer?.tolerance = 0.1
    }

    private func check() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        guard !paused else { return }

        let types = (pb.types ?? []).map(\.rawValue)
        if types.contains(where: ignoredTypes.contains) { return }

        let front = NSWorkspace.shared.frontmostApplication
        if front?.bundleIdentifier == Bundle.main.bundleIdentifier { return }
        let app = front?.localizedName
        let bundle = front?.bundleIdentifier

        // 1. файлы из Finder
        if let urls = pb.readObjects(forClasses: [NSURL.self],
                                     options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            let joined = urls.map(\.path).joined(separator: "\n")
            emit(ClipItem(kind: .files, text: joined, date: Date(), app: app, appBundle: bundle,
                          hash: "f:" + ClipStore.hash(Data(joined.utf8))))
            return
        }
        // 2. текст
        if let s = pb.string(forType: .string), !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            emit(ClipItem(kind: .text, text: s, date: Date(), app: app, appBundle: bundle,
                          hash: "t:" + ClipStore.hash(Data(s.utf8))))
            return
        }
        // 3. картинка (скриншоты, картинки из браузера)
        if let raw = pb.data(forType: .png) ?? pb.data(forType: .tiff),
           let rep = NSBitmapImageRep(data: raw),
           let png = (pb.data(forType: .png) ?? rep.representation(using: .png, properties: [:])),
           png.count < 40_000_000 {
            let h = ClipStore.hash(png)
            emit(ClipItem(kind: .image, imageName: String(h.prefix(24)) + ".png",
                          imageSize: CGSize(width: rep.pixelsWide, height: rep.pixelsHigh),
                          date: Date(), app: app, appBundle: bundle, hash: "i:" + h),
                 imageData: png)
        }
    }

    private func emit(_ item: ClipItem, imageData: Data? = nil) {
        let saved = store.add(item, imageData: imageData)
        onNewItem?(saved)
    }

    // MARK: вставка обратно

    /// Кладёт запись в системный буфер.
    func write(_ item: ClipItem) {
        let pb = NSPasteboard.general
        pb.clearContents()
        switch item.kind {
        case .text:
            pb.setString(item.text ?? "", forType: .string)
        case .image:
            if let url = store.imageURL(item), let data = try? Data(contentsOf: url) {
                pb.setData(data, forType: .png)
                if let tiff = NSImage(data: data)?.tiffRepresentation { pb.setData(tiff, forType: .tiff) }
            }
        case .files:
            pb.writeObjects(item.paths.map { URL(fileURLWithPath: $0) as NSURL })
        }
        lastChange = pb.changeCount   // своё копирование не записываем второй раз
        store.bump(item.id)
    }

    /// Нажимает ⌘V в активной программе. Нужен доступ «Универсальный доступ».
    /// Кладёт в буфер преобразованный текст и добавляет его в историю.
    func writeText(_ s: String) {
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.setString(s, forType: .string)
        lastChange = pb.changeCount
        store.add(ClipItem(kind: .text, text: s, date: Date(), app: "NotchStash",
                           hash: "t:" + ClipStore.hash(Data(s.utf8))))
    }

    static func pressPaste() {
        let src = CGEventSource(stateID: .combinedSessionState)
        let vKey: CGKeyCode = 9   // физическая клавиша V — работает и в русской раскладке
        let down = CGEvent(keyboardEventSource: src, virtualKey: vKey, keyDown: true)
        let up = CGEvent(keyboardEventSource: src, virtualKey: vKey, keyDown: false)
        down?.flags = .maskCommand
        up?.flags = .maskCommand
        down?.post(tap: .cghidEventTap)
        up?.post(tap: .cghidEventTap)
    }

    static var canPaste: Bool { AXIsProcessTrusted() }

    static func askForAccessibility() {
        let key = kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String
        _ = AXIsProcessTrustedWithOptions([key: true] as CFDictionary)
    }
}
